css:
/* From Uiverse.io by zanina-yassine - Tags: form */
.__UIV_SCOPE__ .modal {
  width: 450px;
  background: linear-gradient(180deg, #DCF9E0 0%, #FFFFFF 30.21%);
  box-shadow: 0px 187px 75px rgba(0, 0, 0, 0.01), 0px 105px 63px rgba(0, 0, 0, 0.05), 0px 47px 47px rgba(0, 0, 0, 0.09), 0px 12px 26px rgba(0, 0, 0, 0.1), 0px 0px 0px rgba(0, 0, 0, 0.1);
  border-radius: 16px;
}

.__UIV_SCOPE__ .banner {
  width: 100%;
  height: 30px;
  margin: 0;
  background-size: 100%;
  background-repeat: no-repeat;
}

.__UIV_SCOPE__ .title {
  font-weight: 700;
  font-size: 17px;
  line-height: 21px;
  text-align: center;
  color: #2B2B2F;
  margin-bottom: 15px;
}

.__UIV_SCOPE__ .description {
  max-width: 80%;
  margin: auto;
  font-weight: 600;
  font-size: 11px;
  line-height: 16px;
  text-align: center;
  color: #5F5D6B;
}

.__UIV_SCOPE__ .tab-container {
  display: flex;
  flex-direction: row;
  align-items: flex-start;
  position: relative;
  padding: 2px;
  background-color: #ebebec;
  border-radius: 9px;
  margin: 10px 20px 0px 20px;
}

.__UIV_SCOPE__ .indicator {
  content: "";
  width: 50%;
  height: 28px;
  background: #FFFFFF;
  position: absolute;
  top: 2px;
  left: 2px;
  z-index: 9;
  border: 0.5px solid rgba(0, 0, 0, 0.04);
  box-shadow: 0px 3px 8px rgba(0, 0, 0, 0.12), 0px 3px 1px rgba(0, 0, 0, 0.04);
  border-radius: 7px;
  transition: all 0.2s ease-out;
}

.__UIV_SCOPE__ .tab {
  width: 50%;
  height: 28px;
  position: relative;
  z-index: 99;
  background-color: transparent;
  border: 0;
  outline: none;
  flex: none;
  align-self: stretch;
  flex-grow: 1;
  cursor: pointer;
  font-weight: 500;
}

.__UIV_SCOPE__ .tab--1:hover ~ .indicator {
  left: 2px;
}

.__UIV_SCOPE__ .tab--2:hover ~ .indicator {
  left: calc(50% - 2px);
}

.__UIV_SCOPE__ .benefits {
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.__UIV_SCOPE__ .benefits > span {
  font-size: 15px;
  color: #2B2B2F;
  font-weight: 700;
}

.__UIV_SCOPE__ .benefits ul {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.__UIV_SCOPE__ .benefits ul li {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  gap: 10px;
}

.__UIV_SCOPE__ .benefits ul li span {
  font-weight: 600;
  font-size: 12px;
  color: #5F5D6B;
}

.__UIV_SCOPE__ .modal--footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 20px;
  border-top: 1px solid #ebebec;
}

.__UIV_SCOPE__ .price {
  position: relative;
  font-size: 32px;
  color: #2B2B2F;
  font-weight: 900;
}

.__UIV_SCOPE__ .price sup {
  font-size: 13px;
}

.__UIV_SCOPE__ .price sub {
  width: fit-content;
  position: absolute;
  font-size: 11px;
  color: #5F5D6B;
  bottom: 5px;
  display: inline-block;
}

.__UIV_SCOPE__ .upgrade-btn {
  display: flex;
  flex-direction: row;
  justify-content: center;
  align-items: center;
  width: 215px;
  height: 40px;
  background: #0bdd12;
  box-shadow: 0px 0.5px 0.5px #EFEFEF, 0px 1px 0.5px rgba(239, 239, 239, 0.5);
  border-radius: 7px;
  border: 0;
  outline: none;
  color: #ffffff;
  font-size: 13px;
  font-weight: 600;
  transition: all 0.3s cubic-bezier(0.15, 0.83, 0.66, 1);
}

.__UIV_SCOPE__ .upgrade-btn:hover {
  background-color: #07b90d;
}

.__UIV_SCOPE__ .form {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
